 for u in range(278,301):
  R,G,B=im[v,u];d=float(D[v,u])
  if R>70 and R>1.5*G and R>1.2*B and 1.05<d<1.22:
   pts.append((M@np.array([(u-160)/fx*d,-(v-160)/fy*d,-d,1]))[:3]);cc.append((u,v,im[v,u].tolist(),round(d,3)))
